using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
using DG.Tweening;

namespace BlockNight.Editor
{
    public static class AcceptanceChecks
    {
        static int passed;
        static void Check(bool ok, string label) { if (!ok) throw new Exception("FAIL: " + label); passed++; }
        static void Ready(CombatModel m) { for (int i = 0; i < m.foes.Length; i++) if (m.foes[i].active) m.foes[i].age = 2; }
        static void Place(CombatModel m, int x, int y, Vector2 facing)
        { m.cell = m.target = new Vector2Int(x, y); m.player = CombatModel.Center(m.cell); m.direction = facing; m.moving = m.dashing = false; m.travel = 0; }

        [MenuItem("Block Night/QA/Run Logic Checks")]
        public static void Run() => GridCombatChecks.Menu();

        [MenuItem("Block Night/QA/Combat Fixture")]
        public static void Combat()
        {
            var d = UnityEngine.Object.FindObjectOfType<GameDirector>(); d.Begin(false); d.enabled = false;
            d.model.elapsed = 72; d.model.reward = 12.8f; d.model.score = 4250; d.model.chain = 6;
            int[,] cells = { {1,6},{5,5},{6,2},{2,1},{3,4},{7,7} };
            for (int i = 0; i < 6; i++) { d.model.Spawn(i % 4, CombatModel.Center(new Vector2Int(cells[i,0],cells[i,1]))); d.model.foes[i].age = 3; d.model.foes[i].timer = i % 2 == 0 ? .45f : 1.5f; var c=CombatModel.CellAt(d.model.foes[i].pos);var heading=d.model.foes[i].heading;if(!CombatModel.InBounds(c+heading))heading=-heading;d.model.foes[i].attackTarget=c+heading;d.model.foes[i].attackWindup=i%2==0; }
            d.arena.Render(d.model); d.arena.TimeEffect(false,false,false,.05f); d.hud.Render(d,true); Canvas.ForceUpdateCanvases();
        }
        [MenuItem("Block Night/QA/Slow Fixture")]
        public static void Slow() { Combat(); var d = UnityEngine.Object.FindObjectOfType<GameDirector>(); d.model.Slow(); d.model.foes[0].pending = d.model.foes[1].pending = true; d.arena.Render(d.model); d.arena.TimeEffect(true,false,false,1); d.hud.Render(d,true); }
        [MenuItem("Block Night/QA/Rewind Fixture")]
        public static void Rewind() { Combat(); var d = UnityEngine.Object.FindObjectOfType<GameDirector>(); d.mode = Mode.Rewinding; d.arena.TimeEffect(false,true,false,1); d.hud.Render(d,true); }
        [MenuItem("Block Night/QA/Draft Fixture")]
        public static void Draft() { Combat(); var d = UnityEngine.Object.FindObjectOfType<GameDirector>(); d.mode = Mode.Draft; d.hud.SetOffers(new[]{0,1,5},d.model.levels); d.hud.Render(d,true); }
        [MenuItem("Block Night/QA/Title Fixture")]
        public static void Title() { SceneFlow.ToMenu(); }
        [MenuItem("Block Night/QA/Feedback 1")]
        public static void Feedback1() => Feedback(1);
        [MenuItem("Block Night/QA/Feedback 7")]
        public static void Feedback7() => Feedback(7);
        static void Feedback(int count)
        {
            Combat(); var d = UnityEngine.Object.FindObjectOfType<GameDirector>();
            d.model.chain = count; d.arena.Kill(d.model.player, count, false);
            d.arena.shards.Simulate(.16f, false, false); d.arena.shards.Pause();
            for(int i=0;i<8;i++) d.arena.TimeEffect(false,false,false,.016f);
            d.hud.Banner(ArenaPresentation.TierName(count)); d.hud.Render(d,true);
            foreach(var r in d.arena.shockwaves) if(r.enabled) {r.DOKill();r.transform.DOKill();r.transform.localScale=Vector3.one*(1+ArenaPresentation.Tier(count)*.45f);}
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
using UnityEditor;
using UnityEditor.SceneManagement;

namespace BlockNight.Editor
{
    public static class SceneMigrationV3
    {
        const string Root = "Assets/BlockNight/Scenes/";
        [Serializable] class Layout { public string path; public Vector2 anchorMin, anchorMax, pivot, position, size; public Vector3 scale; public Quaternion rotation; }
        static Dictionary<string, string> Layouts(GameObject canvas)
        {
            var map = new Dictionary<string, string>();
            foreach (var r in canvas.GetComponentsInChildren<RectTransform>(true))
            {
                string path = r.name;
                for (Transform t = r.parent; t != null; t = t.parent) path = t.name + "/" + path;
                map[path] = JsonUtility.ToJson(new Layout { path = path, anchorMin = r.anchorMin, anchorMax = r.anchorMax, pivot = r.pivot, position = r.anchoredPosition, size = r.sizeDelta, scale = r.localScale, rotation = r.localRotation });
            }
            return map;
        }

        [MenuItem("Block Night/Apply v3 Scenes and Phases")]
        public static void Apply()
        {
            if (EditorApplication.isPlaying) throw new InvalidOperationException("先退出运行模式。");
            var director = UnityEngine.Object.FindObjectOfType<GameDirector>();
            if (!director || !director.hud.titlePanel || !director.hud.deathPanel) throw new InvalidOperationException("需要尚未拆分的 BlockNight 场景；已拆分时请直接编辑对应场景。");
            var source = director.gameObject.scene;
            EditorSceneManager.SaveScene(source);
            var before = Layouts(director.hud.gameObject);
            var after = new Dictionary<string, string>();
            var font = AssetDatabase.LoadAssetAtPath<Font>("Assets/BlockNight/Fonts/FZXIANGSU12.TTF");
            if (!font) throw new InvalidOperationException("用户提供的字体尚未导入。");
            foreach (var label in director.hud.GetComponentsInChildren<Text>(true))
            {
                label.font = font;
                if (label.name == "Chain hint") label.text = "冲刺转弯，延续连斩。\n3 / 5 / 7 杀，反馈升级。";
                EditorUtility.SetDirty(label);
            }
            var schedule = AssetDatabase.LoadAssetAtPath<SpawnSchedule>("Assets/BlockNight/Data/SpawnSchedule.asset");
            if (!schedule)
            {
                schedule = ScriptableObject.CreateInstance<SpawnSchedule>();
                schedule.phases = new[]
                {
                    Phase("入阵",25,2,3,EnemyKind.突进方卫),
                    Phase("交锋",35,3,3,EnemyKind.突进方卫,EnemyKind.斜波棱镜),
                    Phase("游猎",40,3,2.7f,EnemyKind.斜波棱镜,EnemyKind.巡格猎手),
                    Phase("脉冲",45,4,2.4f,EnemyKind.突进方卫,EnemyKind.斜波棱镜,EnemyKind.巡格猎手,EnemyKind.逆波脉冲),
                    Phase("压力",35,5,2.2f,EnemyKind.突进方卫,EnemyKind.斜波棱镜,EnemyKind.巡格猎手,EnemyKind.逆波脉冲),
                    Phase("喘息",8,0,2,EnemyKind.突进方卫),
                    Phase("极限",60,5,1.8f,EnemyKind.突进方卫,EnemyKind.斜波棱镜,EnemyKind.巡格猎手,EnemyKind.逆波脉冲)
                };
                AssetDatabase.CreateAsset(schedule, "Assets/BlockNight/Data/SpawnSchedule.asset");
            }
            director.spawnSchedule = schedule; director.routeScenes = true;
            var sourceCamera = source.GetRootGameObjects().SelectMany(r => r.GetComponentsInChildren<Camera>()).First();
            var events = source.GetRootGameObjects().First(r => r.GetComponent<EventSystem>());
            CreateMenu(director, sourceCamera, events, false, font, after);
            SceneManager.SetActiveScene(source);
            CreateMenu(director, sourceCamera, events, true, font, after);
            SceneManager.SetActiveScene(source);
            UnityEngine.Object.DestroyImmediate(director.hud.titlePanel);
            UnityEngine.Object.DestroyImmediate(director.hud.deathPanel);
            director.hud.titlePanel = director.hud.deathPanel = null;
            director.hud.startButton = director.hud.learnButton = director.hud.retryButton = director.hud.homeButton = null;
            director.hud.deathScore = null;
            director.hud.readouts.SetActive(true);
            director.hud.pausePanel.SetActive(false); director.hud.draftPanel.SetActive(false); director.hud.tutorialPanel.SetActive(false);
            foreach (var pair in Layouts(director.hud.gameObject)) after[pair.Key] = pair.Value;
            EditorUtility.SetDirty(director); EditorUtility.SetDirty(director.hud);
            EditorSceneManager.MarkSceneDirty(source); EditorSceneManager.SaveScene(source);
            EditorBuildSettings.scenes = new[] { new EditorBuildSettingsScene(Root + "MainMenu.unity", true), new EditorBuildSettingsScene(Root + "BlockNight.unity", true), new EditorBuildSettingsScene(Root + "GameOver.unity", true) };
            AssetDatabase.SaveAssets();
            var changes = before.Keys.Where(k => !after.ContainsKey(k) || before[k] != after[k]).ToArray();
            Directory.CreateDirectory("Docs/QA");
            File.WriteAllText("Docs/QA/ui-v3-migration.txt", "Original unique UI layouts: " + before.Count + "\nChanged/missing: " + changes.Length + "\n" + string.Join("\n", changes) + "\nFont: FZXIANGSU12.TTF\nScenes: MainMenu, BlockNight, GameOver");
            if (changes.Length > 0) throw new Exception("UI layout audit found changes: " + string.Join(",", changes));
            EditorSceneManager.OpenScene(Root + "MainMenu.unity");
            Debug.Log("V3 migration PASS: original UI geometry retained, user font assigned, phased SO configured, 3 scenes saved.");
        }

        static SpawnPhase Phase(string name, float duration, int count, float interval, params EnemyKind[] kinds)
            => new SpawnPhase { phaseName = name, duration = duration, spawnCount = count, spawnInterval = interval, enemyTypes = kinds };

        static void CreateMenu(GameDirector source, Camera camera, GameObject events, bool gameOver, Font font, Dictionary<string, string> layouts)
        {
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Additive);
            var canvas = UnityEngine.Object.Instantiate(source.hud.gameObject); canvas.name = source.hud.name;
            SceneManager.MoveGameObjectToScene(canvas, scene);
            var hud = canvas.GetComponent<GameHUD>();
            var panel = gameOver ? hud.deathPanel : hud.titlePanel;
            var primary = gameOver ? hud.retryButton : hud.startButton;
            var secondary = gameOver ? hud.homeButton : hud.learnButton;
            var result = hud.deathScore;
            foreach (Transform child in canvas.transform.Cast<Transform>().ToArray()) if (child.gameObject != panel) UnityEngine.Object.DestroyImmediate(child.gameObject);
            panel.SetActive(true);
            var controller = canvas.AddComponent<MenuController>();
            controller.isGameOver = gameOver; controller.primaryButton = primary; controller.secondaryButton = secondary;
            if (gameOver) controller.resultText = result;
            UnityEngine.Object.DestroyImmediate(hud);
            foreach (var label in canvas.GetComponentsInChildren<Text>(true)) label.font = font;
            var audio = UnityEngine.Object.Instantiate(source.audioBus.gameObject); audio.name = "AUDIO — menu";
            SceneManager.MoveGameObjectToScene(audio, scene); controller.audioBus = audio.GetComponent<SynthAudio>();
            var eventObject = UnityEngine.Object.Instantiate(events); eventObject.name = "EventSystem"; SceneManager.MoveGameObjectToScene(eventObject, scene);
            var cam = new GameObject("Main Camera").AddComponent<Camera>(); cam.tag = "MainCamera";
            cam.transform.position = new Vector3(0, 0, -10); cam.orthographic = true; cam.orthographicSize = camera.orthographicSize;
            cam.clearFlags = CameraClearFlags.SolidColor; cam.backgroundColor = camera.backgroundColor;
            cam.gameObject.AddComponent<AudioListener>(); SceneManager.MoveGameObjectToScene(cam.gameObject, scene);
            foreach (var pair in Layouts(canvas)) layouts[pair.Key] = pair.Value;
            EditorSceneManager.SaveScene(scene, Root + (gameOver ? "GameOver" : "MainMenu") + ".unity");
            EditorSceneManager.CloseScene(scene, true);
        }
    }
}

using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using Cinemachine;
using DG.Tweening;

namespace BlockNight
{
    public class ArenaPresentation : MonoBehaviour
    {
        public Transform player;
        public TrailRenderer trail;
        public SpriteRenderer playerSprite;
        public SpriteRenderer[] bodies, warnings, bullets;
        public LineRenderer[] aims;
        public Sprite[] shapes;
        public ParticleSystem shards;
        public Volume volume;
        public CinemachineImpulseSource impulse; // Kept for existing scene serialization; no longer drives feedback.
        public Light2D playerLight;
        public Transform shakeCamera;
        public SpriteRenderer facingMarker;
        public LineRenderer shieldArc;
        public SpriteRenderer[] shockwaves;
        public float cellSize = 1.375f;

        readonly Color[] colors = { new Color(1, .22f, .32f), new Color(.68f, .35f, 1), new Color(1, .64f, .16f), new Color(1, .25f, .69f) };
        Bloom bloom;
        ChromaticAberration chroma;
        ColorAdjustments grade;
        Vignette vignette;
        Vector3 cameraRest, playerScale;
        Tween cameraTween;
        float kick, feedbackTime;
        int feedbackChain, ringIndex;
        bool initialized;
        static readonly int[] Counts = {64, 110, 180, 280};
        static readonly float[] Strengths = {.10f, .18f, .28f, .40f};
        static readonly float[] Corners = {.16f, .27f, .40f, .55f};
        static readonly string[] TierNames = {"破阵", "连破", "狂斩", "极斩"};
        public static int Tier(int kills) => kills >= 7 ? 3 : kills >= 5 ? 2 : kills >= 3 ? 1 : 0;
        public static int ParticleCount(int kills) => Counts[Tier(kills)];
        public static float ShakeStrength(int kills) => Strengths[Tier(kills)];
        public static float BrightCorners(int kills) => Corners[Tier(kills)];
        public static string TierName(int kills) => TierNames[Tier(kills)];
        public Vector3 World(Vector2 p, float z = -.1f) => new Vector3(p.x * cellSize, p.y * cellSize, z);

        void Awake() => Initialize();
        void Initialize()
        {
            if (initialized) return;
            volume.profile.TryGet(out bloom); volume.profile.TryGet(out chroma);
            volume.profile.TryGet(out grade); volume.profile.TryGet(out vignette);
            cameraRest = shakeCamera.localPosition;
            playerScale = player.localScale;
            initialized = true;
        }

        public void ClearEffects()
        {
            Initialize(); trail.Clear(); shards.Clear();
            cameraTween?.Kill(); shakeCamera.localPosition = cameraRest;
            player.DOKill(); player.localScale = playerScale;
            foreach (var ring in shockwaves) { ring.DOKill(); ring.transform.DOKill(); ring.enabled = false; }
            kick = feedbackTime = 0; feedbackChain = 0;
            if(shieldArc)shieldArc.enabled=false;
        }

        public void DashStart()
        {
            Initialize(); trail.Clear();
            player.DOKill(); player.localScale = playerScale;
            player.DOPunchScale(playerScale * .35f, .16f, 1);
        }

        public void Kill(Vector2 p, int n, bool deferred)
        {
            Initialize();
            if (deferred) return;
            int tier = Tier(n);
            if (!shards.isPlaying) shards.Play();
            for (int i = 0; i < ParticleCount(n); i++)
            {
                Vector2 velocity = Random.insideUnitCircle.normalized * Random.Range(2.8f + tier, 5.5f + tier * 1.8f);
                shards.Emit(new ParticleSystem.EmitParams
                {
                    position = World(p, -.3f), velocity = velocity,
                    startColor = Color.Lerp(new Color(.15f, 1, .82f), Color.white, Random.value) * (1.8f + tier * .6f),
                    startSize = Random.Range(.065f + tier * .015f, .13f + tier * .04f),
                    startLifetime = Random.Range(.25f, .52f + tier * .09f)
                }, 1);
            }
            var ring = shockwaves[ringIndex++ % shockwaves.Length];
            ring.DOKill(); ring.transform.DOKill(); ring.enabled = true;
            ring.transform.position = World(p, -.4f);
            ring.transform.localScale = Vector3.one * .25f;
            ring.color = new Color(.35f, 1, .9f, 1) * (1.6f + tier * .35f);
            ring.transform.DOScale(1.4f + tier * .8f, .24f + tier * .05f).SetEase(Ease.OutCubic);
            ring.DOFade(0, .24f + tier * .05f).OnComplete(() => ring.enabled = false);
            feedbackChain = Mathf.Max(feedbackChain, n);
            feedbackTime = .8f; kick = 1;
            cameraTween?.Kill(); shakeCamera.localPosition = cameraRest;
            cameraTween = shakeCamera.DOShakePosition(.14f + Tier(feedbackChain) * .065f,
                new Vector3(ShakeStrength(feedbackChain), ShakeStrength(feedbackChain), 0), 35, 90, false, true)
                .SetUpdate(UpdateType.Late).OnComplete(() => shakeCamera.localPosition = cameraRest);
            player.DOKill(); player.localScale = playerScale;
            player.DOPunchScale(playerScale * (.45f + tier * .15f), .13f, 1);
        }

        public void ShieldBreak(Vector2 p)
        {
            Initialize();shards.Play();
            for(int i=0;i<40;i++){Vector2 v=Random.insideUnitCircle*4;shards.Emit(new ParticleSystem.EmitParams{position=World(p,-.3f),velocity=v,startSize=.08f,startLifetime=.3f,startColor=new Color(.5f,1,1)*2},1);}
        }

        public void Render(CombatModel m)
        {
            Initialize();
            player.position = World(m.player, -.2f);
            playerSprite.color = m.grace > 0 ? Color.white : new Color(.25f, 1, .89f) * 1.5f;
            playerLight.transform.position = player.position;
            trail.emitting = m.dashing;
            Vector2 facing = m.queuedDirection != Vector2.zero ? m.queuedDirection : m.direction;
            facingMarker.transform.position = World(m.player + facing * .36f, -.25f);
            facingMarker.transform.rotation = Quaternion.Euler(0, 0, Mathf.Atan2(facing.y, facing.x) * Mathf.Rad2Deg - 90);
            facingMarker.color = m.dashing ? Color.white : new Color(.25f, 1, .89f);
            for (int i = 0; i < bodies.Length; i++)
            {
                var f = m.foes[i];
                bodies[i].enabled = f.active; warnings[i].enabled = f.active && !f.pending; aims[i].enabled = false;
                if (!f.active) continue;
                bodies[i].transform.position = World(f.pos);
                bodies[i].sprite = shapes[f.type];
                bodies[i].transform.localScale = Vector3.one * (f.type == 3 ? .49f : .56f);
                bodies[i].transform.rotation = Quaternion.Euler(0, 0, f.pending ? 35 : 0);
                Color c = colors[f.type]; bool forming = f.age < m.RulesFor(f.type).spawnWarning;
                bodies[i].color = f.pending ? new Color(.65f, .9f, 1, .5f) : forming ? new Color(c.r, c.g, c.b, .18f) : c * 1.7f;
                var rules=m.RulesFor(f.type);
                bool committed=f.attackWindup||f.moveWindup;
                Vector2Int target=f.attackWindup?f.attackTarget:f.moveTarget;
                bool targetValid=committed&&CombatModel.InBounds(target);
                warnings[i].sprite=shapes[0];
                warnings[i].transform.position=World(targetValid?CombatModel.Center(target):f.pos,0);
                warnings[i].transform.localScale=Vector3.one*(forming?1.15f:targetValid?cellSize*.88f:.7f);
                warnings[i].color=new Color(c.r,c.g,c.b,forming?.45f:targetValid?.25f:.08f);
                if(!forming&&!f.pending&&targetValid){
                    var l=aims[i];l.enabled=true;l.startColor=l.endColor=new Color(c.r,c.g,c.b,.9f);
                    Vector3 p=World(CombatModel.Center(target),-.05f);float half=cellSize*.45f;
                    l.positionCount=5;l.SetPosition(0,p+new Vector3(-half,-half));l.SetPosition(1,p+new Vector3(-half,half));l.SetPosition(2,p+new Vector3(half,half));l.SetPosition(3,p+new Vector3(half,-half));l.SetPosition(4,p+new Vector3(-half,-half));
                }
            }
            for (int i = 0; i < bullets.Length; i++)
            {
                var s = m.shots[i]; bullets[i].enabled = s.active;
                if(s.active){bullets[i].transform.position=World(CombatModel.Center(s.cell),-.15f);bullets[i].sprite=shapes[0];bullets[i].transform.localScale=Vector3.one*cellSize*(s.damaging?.88f:.7f);bullets[i].color=s.damaging?new Color(1,.48f,.12f,.75f)*1.7f:new Color(1,.55f,.15f,.22f);}

            }
            if(shieldArc){shieldArc.enabled=m.dashing&&m.shieldArmed;if(shieldArc.enabled){shieldArc.positionCount=21;float forward=Mathf.Atan2(m.direction.y,m.direction.x);for(int j=0;j<21;j++){float angle=forward+Mathf.Lerp(-Mathf.PI/3,Mathf.PI/3,j/20f);shieldArc.SetPosition(j,World(m.player+new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))*.6f,-.35f));}}}
        }

        public void TimeEffect(bool slow, bool rewind, bool death, float dt)
        {
            Initialize();
            feedbackTime = Mathf.Max(0, feedbackTime - dt);
            if (feedbackTime <= 0) feedbackChain = 0;
            kick = Mathf.MoveTowards(kick, 0, dt * 3);
            bloom.intensity.value = 1.1f + kick * (2.2f + Tier(feedbackChain) * .7f) + (slow ? .5f : 0);
            chroma.intensity.value = Mathf.Lerp(chroma.intensity.value, rewind ? .65f : slow ? .2f : kick * .1f, dt * 12);
            grade.colorFilter.value = Color.Lerp(grade.colorFilter.value, rewind ? new Color(.68f, .43f, 1) : slow ? new Color(.43f, .85f, 1) : Color.white, dt * 8);
            bool bright = feedbackTime > 0 && !death && !rewind;
            vignette.color.value = Color.Lerp(vignette.color.value, bright ? new Color(1.5f, 12f, 8f) : Color.black, Mathf.Clamp01(dt * 16));
            float targetIntensity = bright ? BrightCorners(feedbackChain) : death ? .5f : rewind ? .4f : .22f;
            vignette.intensity.value = Mathf.Lerp(vignette.intensity.value, targetIntensity, Mathf.Clamp01(dt * 18));
        }

        void OnDestroy() { cameraTween?.Kill(); if (shakeCamera) shakeCamera.localPosition = cameraRest; }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace BlockNight
{
    [Serializable]
    public struct Foe
    {
        public bool active, pending;
        public int type, killChain, volley;
        public bool attackWindup, moveWindup;
        public Vector2Int heading, attackTarget, moveTarget;
        public Vector2 pos, aim;
        public float age, timer, hopTimer;
    }

    [Serializable]
    public struct Shot
    {
        public bool active;
        public Vector2 pos, vel;
        public float life;
        public Vector2Int cell, sourceCell, heading;
        public bool damaging;
        public int remaining;
        public float timer, warning, impactDuration;
    }

    [Serializable]
    public class Frame
    {
        public Vector2 player, direction, queuedDirection;
        public Vector2Int cell, target;
        public bool moving, dashing, shieldArmed;
        public float travel;
        public Foe[] foes;
        public Shot[] shots;
        public float elapsed, spawn, reward;
        public int score, kills, chain, bestChain;
        public uint rng;
        public int phaseIndex;
    }

    public class CombatModel
    {
        public const int GridSize = 8, Capacity = 36, Bullets = 80;
        public Vector2 player;
        public Vector2 direction = Vector2.up;
        public Vector2 queuedDirection;
        public int phaseIndex = -1;
        public SpawnSchedule schedule;
        public string PhaseName => schedule == null ? "默认阶段" : schedule.At(elapsed, out _)?.phaseName ?? "阶段结束";
        public Vector2Int cell = new Vector2Int(3, 3), target;
        public bool moving, dashing;
        public float travel;
        public Foe[] foes = new Foe[Capacity];
        public Shot[] shots = new Shot[Bullets];
        public float elapsed, spawn = 1.5f, reward, slow, slowCD, rewindCD, grace;
        public int score, kills, chain, bestChain;
        public uint rng = 7193;
        public bool hit, draft, tutorial;
        public int[] levels = new int[10];
        public bool shieldArmed;
        public float shieldCD;
        public EnemyDefinition[] enemyDefinitions;
        public event Action<Vector2> ShieldBlocked;
        bool dashDuringStep, shieldAtStepStart;
        readonly List<Vector2> movementPath = new List<Vector2>();
        static readonly EnemyRules[] Defaults = {
            new EnemyRules {direction=Vector2Int.right},
            new EnemyRules {action=EnemyAction.斜向冲击波,direction=new Vector2Int(1,1),attackInterval=2.8f},
            new EnemyRules {direction=Vector2Int.up,attackInterval=2,attackWarning=.55f},
            new EnemyRules {action=EnemyAction.斜向冲击波,direction=new Vector2Int(-1,1),attackInterval=3.2f,moveInterval=4,waveRange=5}
        };
        public EnemyRules RulesFor(int type) => enemyDefinitions!=null && type>=0 && type<enemyDefinitions.Length && enemyDefinitions[type] ? enemyDefinitions[type].rules : Defaults[Mathf.Clamp(type,0,Defaults.Length-1)];
        public static int MaxLevel(int id) => id==9?1:3;
        public Balance settings;
        public event Action<Vector2, int, bool> Killed;
        public event Action<int> ChainEnded;

        public CombatModel(Balance config, SpawnSchedule spawnSchedule = null, EnemyDefinition[] definitions = null)
        {
            settings = config; schedule = spawnSchedule; enemyDefinitions = definitions;
            reward = config.upgradeSeconds;
            player = Center(cell);
            target = cell;
        }

        public float Speed => settings.playerSpeed * (1 + .12f * levels[0]);
        public float WalkSpeed => settings.walkSpeed * (1 + .2f * levels[1]);
        public float WorldRate => slow > 0 ? Mathf.Max(.06f, settings.slowRate - .04f * levels[7]) : 1;
        public static Vector2 Center(Vector2Int c) => (Vector2)c - Vector2.one * 3.5f;
        public static Vector2Int CellAt(Vector2 p) => new Vector2Int(Mathf.Clamp(Mathf.RoundToInt(p.x + 3.5f), 0, 7), Mathf.Clamp(Mathf.RoundToInt(p.y + 3.5f), 0, 7));
        public static bool InBounds(Vector2Int c) => c.x >= 0 && c.x < GridSize && c.y >= 0 && c.y < GridSize;
        static Vector2Int Cardinal(Vector2 d) => Mathf.Abs(d.x) > Mathf.Abs(d.y) ? new Vector2Int(d.x > 0 ? 1 : -1, 0) : new Vector2Int(0, d.y > 0 ? 1 : -1);

        public float NextRandom()
        {
            rng ^= rng << 13; rng ^= rng >> 17; rng ^= rng << 5;
            return (rng & 0xffffff) / 16777216f;
        }

        // Different direction: rotate in place. Same direction: exactly one nonlethal step.
        public bool MoveOrTurn(Vector2 requested)
        {
            if (hit || draft || requested == Vector2.zero) return false;
            Vector2Int d = Cardinal(requested);
            if (dashing)
            {
                queuedDirection = d;
                if (travel <= .000001f)
                {
                    direction = queuedDirection; queuedDirection = Vector2.zero;
                    var next = cell + d;
                    if (InBounds(next)) target = next; else FinishDash();
                }
                return true;
            }
            if (moving) return false;
            if (direction != (Vector2)d) { direction = d; return true; }
            if (!InBounds(cell + d)) return false;
            target = cell + d;
            moving = true;
            dashing = false;
            travel = 0;
            return true;
        }

        public void Aim(Vector2 requested) => MoveOrTurn(requested);

        public bool Dash()
        {
            if (moving || hit || draft || !InBounds(cell + Cardinal(direction))) return false;
            chain = 0; queuedDirection = Vector2.zero;
            target = cell + Cardinal(direction);
            moving = dashing = true; shieldArmed = levels[9]>0 && shieldCD<=0;
            travel = 0;
            return true;
        }

        public bool Slow()
        {
            if (slow > 0 || slowCD > 0 || hit || draft) return false;
            slow = settings.slowSeconds + .6f * levels[2];
            return true;
        }

        public static float SegmentDistance(Vector2 p, Vector2 a, Vector2 b)
        {
            var v = b - a;
            return Vector2.Distance(p, a + v * Mathf.Clamp01(Vector2.Dot(p - a, v) / Mathf.Max(.000001f, v.sqrMagnitude)));
        }

        public bool Occupied(Vector2Int c, int except = -1)
        {
            for (int i = 0; i < foes.Length; i++)
                if (i != except && foes[i].active && CellAt(foes[i].pos) == c) return true;
            return false;
        }

        public bool Spawn(int type, Vector2 pos)
        {
            var c = CellAt(pos);
            if (Occupied(c)) return false;
            for (int i = 0; i < foes.Length; i++)
                if (!foes[i].active)
                {
                    var rules=RulesFor(type);
                    foes[i] = new Foe { active = true, type = type, pos = Center(c), timer = Mathf.Max(rules.attackWarning+.1f,rules.attackInterval), heading=rules.Heading, hopTimer = Mathf.Max(rules.moveWarning+.1f,rules.moveInterval) };
                    return true;
                }
            return false;
        }

        void GridImpact(Vector2Int source, Vector2Int heading, int range, EnemyRules rules)
        {
            var targetCell=source+heading;if(!InBounds(targetCell))return;
            for(int i=0;i<shots.Length;i++)if(!shots[i].active){shots[i]=new Shot{active=true,cell=targetCell,sourceCell=source,heading=heading,remaining=range,damaging=true,timer=rules.impactDuration,warning=rules.waveCellWarning,impactDuration=rules.impactDuration,pos=Center(targetCell)};return;}
        }

        Vector2Int PlanTarget(ref Foe f, EnemyRules rules)
        {
            var c=CellAt(f.pos);var targetCell=c+f.heading;
            if(!InBounds(targetCell)&&rules.reverseAtEdge){f.heading=-f.heading;targetCell=c+f.heading;}
            return targetCell;
        }

        void StepEnemy(int index,float dt)
        {
            var f=foes[index];var rules=RulesFor(f.type);
            if(!f.active||f.pending||f.age<rules.spawnWarning||tutorial)return;
            if(!f.moveWindup)f.timer-=dt;
            if(!f.moveWindup&&!f.attackWindup&&f.timer<=rules.attackWarning){f.attackWindup=true;f.timer=Mathf.Max(f.timer,rules.attackWarning);f.attackTarget=PlanTarget(ref f,rules);}
            if(f.attackWindup&&f.timer<=0){
                var c=CellAt(f.pos);var attackHeading=f.attackTarget-c;
                if(InBounds(f.attackTarget)&&attackHeading!=Vector2Int.zero){
                    if(rules.action==EnemyAction.逐格撞击){if(!Occupied(f.attackTarget,index)){GridImpact(c,attackHeading,1,rules);f.pos=Center(f.attackTarget);}}
                    else GridImpact(c,attackHeading,Mathf.Clamp(rules.waveRange,1,8),rules);
                }
                f.attackWindup=false;f.timer=Mathf.Max(rules.attackWarning+.1f,rules.attackInterval);f.volley++;
            }
            if(rules.action==EnemyAction.斜向冲击波){
                // Movement waits while the wave attack is committed, so its warning never moves.
                if(!f.attackWindup){
                    f.hopTimer-=dt;
                    if(!f.moveWindup&&f.hopTimer<=rules.moveWarning){f.moveWindup=true;f.hopTimer=Mathf.Max(f.hopTimer,rules.moveWarning);f.moveTarget=PlanTarget(ref f,rules);}
                    if(f.moveWindup&&f.hopTimer<=0){var c=CellAt(f.pos);if(InBounds(f.moveTarget)&&!Occupied(f.moveTarget,index)){GridImpact(c,f.moveTarget-c,1,rules);f.pos=Center(f.moveTarget);}f.moveWindup=false;f.hopTimer=Mathf.Max(rules.moveWarning+.1f,rules.moveInterval);}
                }
            }
            foes[index]=f;
        }

        static bool CrossesTile(Vector2 from,Vector2 to,Vector2 center)
        {
            float lo=0,hi=1;Vector2 d=to-from;
            for(int axis=0;axis<2;axis++){
                float start=axis==0?from.x:from.y,delta=axis==0?d.x:d.y,c=axis==0?center.x:center.y;
                if(Mathf.Abs(delta)<.000001f){if(Mathf.Abs(start-c)>.45f)return false;continue;}
                float a=(c-.45f-start)/delta,b=(c+.45f-start)/delta;if(a>b){float t=a;a=b;b=t;}lo=Mathf.Max(lo,a);hi=Mathf.Min(hi,b);if(lo>hi)return false;
            }
            return true;
        }

        void ResolveImpact(ref Shot strike)
        {
            if(!strike.damaging||grace>0||hit)return;
            bool touches=false;
            for(int i=1;i<movementPath.Count;i++)if(CrossesTile(movementPath[i-1],movementPath[i],Center(strike.cell))){touches=true;break;}
            if(!touches)return;
            Vector2 incoming=(Center(strike.sourceCell)-player).normalized;
            if((dashing||dashDuringStep)&&(shieldArmed||shieldAtStepStart)&&shieldCD<=0&&Vector2.Dot(direction,incoming)>=.5f){shieldArmed=false;shieldCD=8;strike.active=false;ShieldBlocked?.Invoke(player);return;}
            hit=true;
        }

        void StepStrike(ref Shot strike,float dt)
        {
            float remainingTime=dt;
            while(strike.active&&remainingTime>0){
                ResolveImpact(ref strike);if(!strike.active||hit)return;
                float part=Mathf.Min(remainingTime,Mathf.Max(0,strike.timer));strike.timer-=part;remainingTime-=part;
                if(strike.timer>.000001f)break;
                if(!strike.damaging){strike.damaging=true;strike.timer=strike.impactDuration;ResolveImpact(ref strike);}
                else {strike.remaining--;var next=strike.cell+strike.heading;if(strike.remaining<=0||!InBounds(next)){strike.active=false;break;}strike.sourceCell=strike.cell;strike.cell=next;strike.pos=Center(next);strike.damaging=false;strike.timer=strike.warning;}
            }
        }

        public void Release()
        {
            for (int i = 0; i < foes.Length; i++)
                if (foes[i].pending)
                {
                    Killed?.Invoke(foes[i].pos, Mathf.Max(1, foes[i].killChain), false);
                    foes[i].pending = foes[i].active = false;
                }
        }

        void Slash(Vector2 from, Vector2 to)
        {
            for (int i = 0; i < foes.Length; i++)
            {
                var f = foes[i];
                if (!f.active || f.pending || f.age < RulesFor(f.type).spawnWarning || SegmentDistance(f.pos, from, to) > .28f) continue;
                chain++; kills++;
                score += Mathf.RoundToInt(100 * (1 + .25f * Mathf.Min(chain - 1, 12)) * (1 + .25f * levels[6]));
                reward -= settings.killSeconds + .35f * levels[5];
                f.killChain = chain;
                f.pending = slow > 0;
                f.active = f.pending;
                foes[i] = f;
                Killed?.Invoke(f.pos, chain, f.pending);
            }
        }

        void AdvancePlayer(float dt)
        {
            if (!moving) return;
            float remaining = dt;
            while (moving && remaining > .000001f)
            {
                float speed = dashing ? Speed : WalkSpeed;
                float slice = Mathf.Min(remaining, (1 - travel) / speed);
                Vector2 before = player;
                travel = Mathf.Min(1, travel + slice * speed);
                player = Vector2.Lerp(Center(cell), Center(target), travel);
                movementPath.Add(player);
                if (dashing) Slash(before, player);
                remaining -= slice;
                if (travel < .99999f) break;
                cell = target;
                player = Center(cell);
                travel = 0;
                if (dashing && queuedDirection != Vector2.zero) { direction = queuedDirection; queuedDirection = Vector2.zero; }
                var next = cell + Cardinal(direction);
                if (dashing && InBounds(next)) { target = next; continue; }
                moving = false;
                if (dashing) FinishDash();
            }
        }

        void FinishDash()
        {
            moving = dashing = false; shieldArmed=false; queuedDirection = Vector2.zero;
            if (chain > 0)
            {
                score += 25 * chain * chain;
                reward -= Mathf.Min(3, .2f * chain);
                bestChain = Mathf.Max(bestChain, chain);
                ChainEnded?.Invoke(chain);
            }
            chain = 0;
        }

        void SpawnBatch(SpawnPhase phase)
        {
            if (phase.enemyTypes == null || phase.enemyTypes.Length == 0 || phase.spawnCount <= 0) return;
            var available = new List<Vector2Int>();
            for (int x = 0; x < 8; x++) for (int y = 0; y < 8; y++)
            {
                var c = new Vector2Int(x, y);
                if (Mathf.Abs(x - cell.x) + Mathf.Abs(y - cell.y) >= 2 && !Occupied(c)) available.Add(c);
            }
            int count = Mathf.Min(phase.spawnCount, Capacity, available.Count);
            for (int i = 0; i < count; i++)
            {
                int index = (int)(NextRandom() * available.Count);
                var c = available[index]; available.RemoveAt(index);
                int type = (int)phase.enemyTypes[(int)(NextRandom() * phase.enemyTypes.Length)];
                if (!Spawn(type, Center(c))) break;
            }
        }

        public void Step(float dt)
        {
            if (hit || draft) return;
            grace = Mathf.Max(0, grace - dt);
            slowCD = Mathf.Max(0, slowCD - dt);
            rewindCD = Mathf.Max(0, rewindCD - dt);
            shieldCD = Mathf.Max(0,shieldCD-dt);
            float wd = dt * WorldRate;
            if (slow > 0)
            {
                slow -= dt;
                if (slow <= 0) { slow = 0; slowCD = Mathf.Max(4, settings.slowCooldown - 1.5f * levels[3]); Release(); }
            }
            if (!tutorial)
            {
                elapsed += wd; reward -= dt;
                int nextPhase = 0;
                var phase = schedule == null ? SpawnSchedule.Fallback : schedule.At(elapsed, out nextPhase);
                if (phaseIndex != nextPhase) { phaseIndex = nextPhase; spawn = 0; }
                spawn -= wd;
                if (phase != null && spawn <= 0)
                {
                    spawn = Mathf.Max(.2f, phase.spawnInterval);
                    SpawnBatch(phase);
                }
            }
            for (int i = 0; i < foes.Length; i++) if (foes[i].active && !foes[i].pending) foes[i].age += wd;
            dashDuringStep=dashing;shieldAtStepStart=shieldArmed;
            movementPath.Clear();movementPath.Add(player);
            AdvancePlayer(dt);if(movementPath.Count==1)movementPath.Add(player);
            for(int i=0;i<foes.Length;i++)StepEnemy(i,wd);
            for(int i=0;i<shots.Length;i++)if(shots[i].active){var strike=shots[i];StepStrike(ref strike,wd);shots[i]=strike;}
            // A lethal hit interrupts by death, but cannot be used to steer an ongoing slash.
            if (hit) { moving = dashing = false; shieldArmed=false; }
            if (reward <= 0 && !tutorial && !hit && !dashing) { reward = 0; draft = true; }
        }

        public Frame Capture() => new Frame
        {
            player = player, direction = direction, queuedDirection = queuedDirection, phaseIndex = phaseIndex, shieldArmed=shieldArmed, cell = cell, target = target, moving = moving, dashing = dashing, travel = travel,
            foes = (Foe[])foes.Clone(), shots = (Shot[])shots.Clone(), elapsed = elapsed, spawn = spawn, reward = reward,
            score = score, kills = kills, chain = chain, bestChain = bestChain, rng = rng
        };

        public void Restore(Frame f)
        {
            player = f.player; direction = f.direction; queuedDirection = f.queuedDirection; phaseIndex = f.phaseIndex; cell = f.cell; target = f.target; moving = f.moving; dashing = f.dashing; travel = f.travel; shieldArmed=f.shieldArmed && shieldCD<=0 && dashing;
            Array.Copy(f.foes, foes, Capacity); Array.Copy(f.shots, shots, Bullets);
            elapsed = f.elapsed; spawn = f.spawn; reward = f.reward; score = f.score; kills = f.kills;
            chain = f.chain; bestChain = f.bestChain; rng = f.rng; hit = draft = false;
        }

        public int[] Offers()
        {
            var bag = new List<int>();
            for (int i = 0; i < levels.Length; i++) if (levels[i] < MaxLevel(i)) bag.Add(i);
            var result = new int[3];
            for (int i = 0; i < 3; i++)
            {
                if (bag.Count == 0) { result[i] = 10; continue; }
                int n = (int)(NextRandom() * bag.Count); result[i] = bag[n]; bag.RemoveAt(n);
            }
            return result;
        }
        public void Choose(int id) { if (id < levels.Length) levels[id]=Mathf.Min(MaxLevel(id),levels[id]+1); else score += 2500; reward = settings.upgradeSeconds; draft = false; }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace BlockNight
{
    public enum Mode { Title, Playing, Paused, Draft, Dying, Dead, Rewinding }

    public class GameDirector : MonoBehaviour
    {
        public Balance balance;
        public SpawnSchedule spawnSchedule;
        public EnemyDefinition[] enemyDefinitions;
        [HideInInspector] public bool routeScenes = true;
        bool started;
        public ArenaPresentation arena;
        public GameHUD hud;
        public SynthAudio audioBus;
        public CombatModel model;
        public Mode mode;
        public int tutorialStep = -1;
        public float danger;
        readonly List<Frame> history = new List<Frame>();
        float sample, rewindClock;
        int rewindFrom;
        int[] offers;
        bool returnTutorial;
        Vector2Int tutorialStart;

        public void Awake()
        {
            Application.runInBackground = true;
            NewModel(); mode = Mode.Title;
            hud.Bind(this); arena.Render(model);
        }

        void Start() { if (!started) Begin(SceneFlow.NextRunTutorial); }

        void NewModel()
        {
            model = new CombatModel(balance, spawnSchedule, enemyDefinitions);
            model.rng = (uint)System.Environment.TickCount | 1u;
            model.Killed += (p, n, deferred) =>
            {
                arena.Kill(p, n, deferred);
                if (!deferred) audioBus.Cue(2, n);
                hud.RewardPunch();
            };
            model.ShieldBlocked += p => { arena.ShieldBreak(p);audioBus.Cue(3);hud.Banner("盾弧破碎 / 8 秒重充"); };
            model.ChainEnded += n => { hud.Banner("连斩 " + n.ToString("00") + " / " + ArenaPresentation.TierName(n)); audioBus.Cue(3, n); };
            history.Clear(); sample = 0;
        }

        public void Begin(bool tutorial)
        {
            started = true;
            NewModel(); tutorialStep = tutorial ? 0 : -1;
            model.tutorial = tutorial; mode = Mode.Playing;
            if (tutorial) PlacePlayer(new Vector2Int(3, 1));
            tutorialStart = model.cell;
            arena.ClearEffects(); audioBus.Cue(0);
        }

        void PlacePlayer(Vector2Int c)
        {
            model.cell = model.target = c;
            model.player = CombatModel.Center(c);
            model.direction = Vector2.up;
            model.moving = model.dashing = false; model.travel = 0;
        }

        public void Home() { if (routeScenes) { SceneFlow.ToMenu(); return; } NewModel(); mode = Mode.Title; tutorialStep = -1; arena.ClearEffects(); }
        public void Pause() { if (mode == Mode.Playing) mode = Mode.Paused; else if (mode == Mode.Paused) mode = Mode.Playing; }
        public void Choose(int index)
        {
            if (mode != Mode.Draft) return;
            model.Choose(offers[index]); history.Clear(); sample = 0;
            mode = Mode.Playing; audioBus.Cue(4);
        }

        public void MoveOrTurn(Vector2 direction)
        {
            if (mode != Mode.Playing) return;
            Vector2 oldDirection = model.direction;
            if (!model.MoveOrTurn(direction)) return;
            audioBus.Cue(1);
            if (tutorialStep == 0 && oldDirection != model.direction) tutorialStep = 1;
        }

        public bool StartSlash()
        {
            if (mode != Mode.Playing || !model.Dash()) return false;
            arena.DashStart(); audioBus.Cue(1, 4); return true;
        }

        public bool ActivateSlow()
        {
            if (mode != Mode.Playing || !model.Slow()) return false;
            audioBus.Cue(4);
            if (tutorialStep == 3)
            {
                PlacePlayer(new Vector2Int(3, 0));
                for (int j = 2; j <= 6; j++) model.Spawn(0, CombatModel.Center(new Vector2Int(3, j)));
                for (int j = 0; j < model.foes.Length; j++) if (model.foes[j].active) model.foes[j].age = balance.spawnWarning;
                tutorialStep = 4; StartSlash();
            }
            return true;
        }

        public bool Rewind()
        {
            if ((mode != Mode.Playing && mode != Mode.Dying) || model.dashing || model.rewindCD > 0 || history.Count < 11) return false;
            returnTutorial = model.tutorial;
            rewindFrom = history.Count - 1; rewindClock = 0; mode = Mode.Rewinding;
            if (model.slow > 0) model.slowCD = Mathf.Max(model.slowCD, balance.slowCooldown - 1.5f * model.levels[3]);
            model.slow = 0; audioBus.Cue(5); arena.ClearEffects(); return true;
        }

        void Update() { GameInput.Poll(); Tick(Mathf.Min(Time.unscaledDeltaTime, .05f)); }

        public void Tick(float dt)
        {
            if (GameInput.Down(KeyCode.M)) audioBus.ToggleMute();
            if (GameInput.Down(KeyCode.Escape)) Pause();
            if (mode == Mode.Rewinding)
            {
                rewindClock += dt;
                int index = Mathf.Clamp(Mathf.RoundToInt(Mathf.Lerp(rewindFrom, 0, rewindClock / .85f)), 0, rewindFrom);
                model.Restore(history[index]);
                if (rewindClock >= .85f)
                {
                    history.Clear(); sample = 0; model.Release();
                    model.grace = .55f + .25f * model.levels[8];
                    model.rewindCD = Mathf.Max(6, balance.rewindCooldown - 2 * model.levels[4]);
                    mode = Mode.Playing;
                    if (returnTutorial && tutorialStep == 5) tutorialStep = 6;
                }
            }
            else if (mode == Mode.Dying)
            {
                danger -= dt;
                if (GameInput.Down(KeyCode.L) && Rewind()) { }
                else if (danger <= 0) { mode = Mode.Dead; audioBus.Cue(6); }
            }
            else if (mode == Mode.Playing)
            {
                if (!(GameInput.Down(KeyCode.L) && Rewind()))
                {
                    if (GameInput.Down(KeyCode.W) || GameInput.Down(KeyCode.UpArrow)) MoveOrTurn(Vector2.up);
                    if (GameInput.Down(KeyCode.S) || GameInput.Down(KeyCode.DownArrow)) MoveOrTurn(Vector2.down);
                    if (GameInput.Down(KeyCode.A) || GameInput.Down(KeyCode.LeftArrow)) MoveOrTurn(Vector2.left);
                    if (GameInput.Down(KeyCode.D) || GameInput.Down(KeyCode.RightArrow)) MoveOrTurn(Vector2.right);
                    if (GameInput.Down(KeyCode.J)) StartSlash();
                    if (GameInput.Down(KeyCode.K)) ActivateSlow();
                    model.Step(dt);
                    sample += dt;
                    if (sample >= .05f)
                    {
                        sample -= .05f; history.Add(model.Capture());
                        if (history.Count > Mathf.CeilToInt(balance.rewindSeconds / .05f) + 1) history.RemoveAt(0);
                    }
                    AdvanceTutorial();
                    if (tutorialStep == 6 && GameInput.Down(KeyCode.Return)) Begin(false);
                    if (model.hit) { mode = Mode.Dying; danger = .6f; audioBus.Cue(6); }
                    else if (model.draft) { offers = model.Offers(); hud.SetOffers(offers, model.levels); mode = Mode.Draft; audioBus.Cue(4); }
                }
            }
            else if (mode == Mode.Draft)
            {
                if (GameInput.Down(KeyCode.Alpha1)) Choose(0);
                if (GameInput.Down(KeyCode.Alpha2)) Choose(1);
                if (GameInput.Down(KeyCode.Alpha3)) Choose(2);
            }
            if (mode == Mode.Dead && routeScenes) { SceneFlow.Finish(model); return; }
            arena.Render(model);
            arena.TimeEffect(model.slow > 0, mode == Mode.Rewinding, mode == Mode.Dying, dt);
            hud.Render(this, history.Count >= 11);
            audioBus.Tick(model.elapsed, model.WorldRate, mode == Mode.Playing, dt);
        }

        void AdvanceTutorial()
        {
            if (tutorialStep == 1 && !model.moving && model.cell != tutorialStart)
            {
                tutorialStep = 2;
                for (int j = 3; j <= 5; j++) model.Spawn(0, CombatModel.Center(new Vector2Int(model.cell.x, j)));
            }
            if (tutorialStep == 2 && model.kills > 0 && !model.dashing) tutorialStep = 3;
            if (tutorialStep == 4 && model.slow <= 0) tutorialStep = 5;
        }
    }
}

